import numpy as np
def matrix_elements(X, l, m, n):
	C = np.zeros((16,16))
	C[0,0] = X[0, 0]
	C[0,1] = m*X[0, 2]
	C[0,2] = n*X[0, 2]
	C[0,3] = l*X[0, 2]
	C[0,4] = np.sqrt(3)*l*m*X[0, 6]
	C[0,5] = np.sqrt(3)*m*n*X[0, 6]
	C[0,6] = (1.5*n**2 - 0.5)*X[0, 6]
	C[0,7] = np.sqrt(3)*l*n*X[0, 6]
	C[0,8] = np.sqrt(3)*(-2*m**2 - n**2 + 1)*X[0, 6]/2
	C[0,9] = np.sqrt(10)*m*(-4*m**2 - 3*n**2 + 3)*X[0, 12]/4
	C[0,10] = np.sqrt(15)*l*m*n*X[0, 12]
	C[0,11] = np.sqrt(6)*m*(5*n**2 - 1)*X[0, 12]/4
	C[0,12] = n*(5*n**2 - 3)*X[0, 12]/2
	C[0,13] = np.sqrt(6)*l*(5*n**2 - 1)*X[0, 12]/4
	C[0,14] = np.sqrt(15)*n*(-2*m**2 - n**2 + 1)*X[0, 12]/2
	C[0,15] = np.sqrt(10)*l*(-4*m**2 - n**2 + 1)*X[0, 12]/4
	C[1,0] = m*X[2, 0]
	C[1,1] = -m**2*X[1, 1] + m**2*X[2, 2] + X[1, 1]
	C[1,2] = m*n*(-X[1, 1] + X[2, 2])
	C[1,3] = l*m*(-X[1, 1] + X[2, 2])
	C[1,4] = l*(-2*m**2*X[1, 5] + np.sqrt(3)*m**2*X[2, 6] + X[1, 5])
	C[1,5] = n*(-2*m**2*X[1, 5] + np.sqrt(3)*m**2*X[2, 6] + X[1, 5])
	C[1,6] = m*(-1.0*np.sqrt(3)*n**2*X[1, 5] + 1.5*n**2*X[2, 6] - 0.5*X[2, 6])
	C[1,7] = l*m*n*(-2*X[1, 5] + np.sqrt(3)*X[2, 6])
	C[1,8] = m*(4*m**2*X[1, 5] - 2*np.sqrt(3)*m**2*X[2, 6] + 2*n**2*X[1, 5] - np.sqrt(3)*n**2*X[2, 6] - 4*X[1, 5] + np.sqrt(3)*X[2, 6])/2
	C[1,9] = np.sqrt(15)*m**4*X[1, 11] - np.sqrt(10)*m**4*X[2, 12] + 3*np.sqrt(15)*m**2*n**2*X[1, 11]/4 - 3*np.sqrt(10)*m**2*n**2*X[2, 12]/4 - 5*np.sqrt(15)*m**2*X[1, 11]/4 + 3*np.sqrt(10)*m**2*X[2, 12]/4 - np.sqrt(15)*n**2*X[1, 11]/4 + np.sqrt(15)*X[1, 11]/4
	C[1,10] = l*n*(-3*np.sqrt(10)*m**2*X[1, 11] + 2*np.sqrt(15)*m**2*X[2, 12] + np.sqrt(10)*X[1, 11])/2
	C[1,11] = -15*m**2*n**2*X[1, 11]/4 + 5*np.sqrt(6)*m**2*n**2*X[2, 12]/4 + m**2*X[1, 11]/4 - np.sqrt(6)*m**2*X[2, 12]/4 + 5*n**2*X[1, 11]/4 - X[1, 11]/4
	C[1,12] = m*n*(-5*np.sqrt(6)*n**2*X[1, 11] + 10*n**2*X[2, 12] + np.sqrt(6)*X[1, 11] - 6*X[2, 12])/4
	C[1,13] = l*m*(-15*n**2*X[1, 11] + 5*np.sqrt(6)*n**2*X[2, 12] + X[1, 11] - np.sqrt(6)*X[2, 12])/4
	C[1,14] = m*n*(6*np.sqrt(10)*m**2*X[1, 11] - 4*np.sqrt(15)*m**2*X[2, 12] + 3*np.sqrt(10)*n**2*X[1, 11] - 2*np.sqrt(15)*n**2*X[2, 12] - 5*np.sqrt(10)*X[1, 11] + 2*np.sqrt(15)*X[2, 12])/4
	C[1,15] = l*m*(4*np.sqrt(15)*m**2*X[1, 11] - 4*np.sqrt(10)*m**2*X[2, 12] + np.sqrt(15)*n**2*X[1, 11] - np.sqrt(10)*n**2*X[2, 12] - 3*np.sqrt(15)*X[1, 11] + np.sqrt(10)*X[2, 12])/4
	C[2,0] = n*X[2, 0]
	C[2,1] = m*n*(-X[1, 1] + X[2, 2])
	C[2,2] = -n**2*X[1, 1] + n**2*X[2, 2] + X[1, 1]
	C[2,3] = l*n*(-X[1, 1] + X[2, 2])
	C[2,4] = l*m*n*(-2*X[1, 5] + np.sqrt(3)*X[2, 6])
	C[2,5] = m*(-2*n**2*X[1, 5] + np.sqrt(3)*n**2*X[2, 6] + X[1, 5])
	C[2,6] = n*(-1.0*np.sqrt(3)*n**2*X[1, 5] + 1.5*n**2*X[2, 6] + 1.0*np.sqrt(3)*X[1, 5] - 0.5*X[2, 6])
	C[2,7] = l*(-2*n**2*X[1, 5] + np.sqrt(3)*n**2*X[2, 6] + X[1, 5])
	C[2,8] = n*(4*m**2*X[1, 5] - 2*np.sqrt(3)*m**2*X[2, 6] + 2*n**2*X[1, 5] - np.sqrt(3)*n**2*X[2, 6] - 2*X[1, 5] + np.sqrt(3)*X[2, 6])/2
	C[2,9] = m*n*(4*np.sqrt(15)*m**2*X[1, 11] - 4*np.sqrt(10)*m**2*X[2, 12] + 3*np.sqrt(15)*n**2*X[1, 11] - 3*np.sqrt(10)*n**2*X[2, 12] - 3*np.sqrt(15)*X[1, 11] + 3*np.sqrt(10)*X[2, 12])/4
	C[2,10] = l*m*(-3*np.sqrt(10)*n**2*X[1, 11] + 2*np.sqrt(15)*n**2*X[2, 12] + np.sqrt(10)*X[1, 11])/2
	C[2,11] = m*n*(-15*n**2*X[1, 11] + 5*np.sqrt(6)*n**2*X[2, 12] + 11*X[1, 11] - np.sqrt(6)*X[2, 12])/4
	C[2,12] = -5*np.sqrt(6)*n**4*X[1, 11]/4 + 5*n**4*X[2, 12]/2 + 3*np.sqrt(6)*n**2*X[1, 11]/2 - 3*n**2*X[2, 12]/2 - np.sqrt(6)*X[1, 11]/4
	C[2,13] = l*n*(-15*n**2*X[1, 11] + 5*np.sqrt(6)*n**2*X[2, 12] + 11*X[1, 11] - np.sqrt(6)*X[2, 12])/4
	C[2,14] = 3*np.sqrt(10)*m**2*n**2*X[1, 11]/2 - np.sqrt(15)*m**2*n**2*X[2, 12] - np.sqrt(10)*m**2*X[1, 11]/2 + 3*np.sqrt(10)*n**4*X[1, 11]/4 - np.sqrt(15)*n**4*X[2, 12]/2 - np.sqrt(10)*n**2*X[1, 11] + np.sqrt(15)*n**2*X[2, 12]/2 + np.sqrt(10)*X[1, 11]/4
	C[2,15] = l*n*(4*np.sqrt(15)*m**2*X[1, 11] - 4*np.sqrt(10)*m**2*X[2, 12] + np.sqrt(15)*n**2*X[1, 11] - np.sqrt(10)*n**2*X[2, 12] - np.sqrt(15)*X[1, 11] + np.sqrt(10)*X[2, 12])/4
	C[3,0] = l*X[2, 0]
	C[3,1] = l*m*(-X[1, 1] + X[2, 2])
	C[3,2] = l*n*(-X[1, 1] + X[2, 2])
	C[3,3] = m**2*X[1, 1] - m**2*X[2, 2] + n**2*X[1, 1] - n**2*X[2, 2] + X[2, 2]
	C[3,4] = m*(2*m**2*X[1, 5] - np.sqrt(3)*m**2*X[2, 6] + 2*n**2*X[1, 5] - np.sqrt(3)*n**2*X[2, 6] - X[1, 5] + np.sqrt(3)*X[2, 6])
	C[3,5] = l*m*n*(-2*X[1, 5] + np.sqrt(3)*X[2, 6])
	C[3,6] = l*(-1.0*np.sqrt(3)*n**2*X[1, 5] + 1.5*n**2*X[2, 6] - 0.5*X[2, 6])
	C[3,7] = n*(2*m**2*X[1, 5] - np.sqrt(3)*m**2*X[2, 6] + 2*n**2*X[1, 5] - np.sqrt(3)*n**2*X[2, 6] - X[1, 5] + np.sqrt(3)*X[2, 6])
	C[3,8] = l*(4*m**2*X[1, 5] - 2*np.sqrt(3)*m**2*X[2, 6] + 2*n**2*X[1, 5] - np.sqrt(3)*n**2*X[2, 6] + np.sqrt(3)*X[2, 6])/2
	C[3,9] = l*m*(4*np.sqrt(15)*m**2*X[1, 11] - 4*np.sqrt(10)*m**2*X[2, 12] + 3*np.sqrt(15)*n**2*X[1, 11] - 3*np.sqrt(10)*n**2*X[2, 12] - np.sqrt(15)*X[1, 11] + 3*np.sqrt(10)*X[2, 12])/4
	C[3,10] = m*n*(3*np.sqrt(10)*m**2*X[1, 11] - 2*np.sqrt(15)*m**2*X[2, 12] + 3*np.sqrt(10)*n**2*X[1, 11] - 2*np.sqrt(15)*n**2*X[2, 12] - 2*np.sqrt(10)*X[1, 11] + 2*np.sqrt(15)*X[2, 12])/2
	C[3,11] = l*m*(-15*n**2*X[1, 11] + 5*np.sqrt(6)*n**2*X[2, 12] + X[1, 11] - np.sqrt(6)*X[2, 12])/4
	C[3,12] = l*n*(-5*np.sqrt(6)*n**2*X[1, 11] + 10*n**2*X[2, 12] + np.sqrt(6)*X[1, 11] - 6*X[2, 12])/4
	C[3,13] = 15*m**2*n**2*X[1, 11]/4 - 5*np.sqrt(6)*m**2*n**2*X[2, 12]/4 - m**2*X[1, 11]/4 + np.sqrt(6)*m**2*X[2, 12]/4 + 15*n**4*X[1, 11]/4 - 5*np.sqrt(6)*n**4*X[2, 12]/4 - 11*n**2*X[1, 11]/4 + 3*np.sqrt(6)*n**2*X[2, 12]/2 - np.sqrt(6)*X[2, 12]/4
	C[3,14] = l*n*(6*np.sqrt(10)*m**2*X[1, 11] - 4*np.sqrt(15)*m**2*X[2, 12] + 3*np.sqrt(10)*n**2*X[1, 11] - 2*np.sqrt(15)*n**2*X[2, 12] - np.sqrt(10)*X[1, 11] + 2*np.sqrt(15)*X[2, 12])/4
	C[3,15] = -np.sqrt(15)*m**4*X[1, 11] + np.sqrt(10)*m**4*X[2, 12] - 5*np.sqrt(15)*m**2*n**2*X[1, 11]/4 + 5*np.sqrt(10)*m**2*n**2*X[2, 12]/4 + 3*np.sqrt(15)*m**2*X[1, 11]/4 - 5*np.sqrt(10)*m**2*X[2, 12]/4 - np.sqrt(15)*n**4*X[1, 11]/4 + np.sqrt(10)*n**4*X[2, 12]/4 + np.sqrt(15)*n**2*X[1, 11]/4 - np.sqrt(10)*n**2*X[2, 12]/2 + np.sqrt(10)*X[2, 12]/4
	C[4,0] = np.sqrt(3)*l*m*X[6, 0]
