	C[4,2] = l*m*n*(-2*X[5, 1] + np.sqrt(3)*X[6, 2])
	C[4,3] = m*(2*m**2*X[5, 1] - np.sqrt(3)*m**2*X[6, 2] + 2*n**2*X[5, 1] - np.sqrt(3)*n**2*X[6, 2] - X[5, 1] + np.sqrt(3)*X[6, 2])
	C[4,4] = -1.0*m**4*X[4, 4] + 4.0*m**4*X[5, 5] - 3.0*m**4*X[6, 6] - 1.0*m**2*n**2*X[4, 4] + 4.0*m**2*n**2*X[5, 5] - 3.0*m**2*n**2*X[6, 6] + 1.0*m**2*X[4, 4] - 4.0*m**2*X[5, 5] + 3.0*m**2*X[6, 6] + 1.0*n**2*X[4, 4] - 1.0*n**2*X[5, 5] + 1.0*X[5, 5]
	C[4,5] = l*n*(1.0*m**2*X[4, 4] - 4.0*m**2*X[5, 5] + 3.0*m**2*X[6, 6] - 1.0*X[4, 4] + 1.0*X[5, 5])
	C[4,6] = np.sqrt(3)*l*m*(0.5*n**2*X[4, 4] - 2.0*n**2*X[5, 5] + 1.5*n**2*X[6, 6] + 0.5*X[4, 4] - 0.5*X[6, 6])
	C[4,7] = m*n*(-1.0*m**2*X[4, 4] + 4.0*m**2*X[5, 5] - 3.0*m**2*X[6, 6] - 1.0*n**2*X[4, 4] + 4.0*n**2*X[5, 5] - 3.0*n**2*X[6, 6] - 3.0*X[5, 5] + 3.0*X[6, 6])
	C[4,8] = l*m*(-1.0*m**2*X[4, 4] + 4.0*m**2*X[5, 5] - 3.0*m**2*X[6, 6] - 0.5*n**2*X[4, 4] + 2.0*n**2*X[5, 5] - 1.5*n**2*X[6, 6] + 0.5*X[4, 4] - 2.0*X[5, 5] + 1.5*X[6, 6])
	C[4,9] = l*(-1.0*np.sqrt(6)*m**4*X[4, 10] + 2.0*np.sqrt(15)*m**4*X[5, 11] - 1.0*np.sqrt(30)*m**4*X[6, 12] - 0.75*np.sqrt(6)*m**2*n**2*X[4, 10] + 1.5*np.sqrt(15)*m**2*n**2*X[5, 11] - 0.75*np.sqrt(30)*m**2*n**2*X[6, 12] + 0.75*np.sqrt(6)*m**2*X[4, 10] - 1.5*np.sqrt(15)*m**2*X[5, 11] + 0.75*np.sqrt(30)*m**2*X[6, 12] + 0.5*np.sqrt(6)*n**2*X[4, 10] - 0.25*np.sqrt(15)*n**2*X[5, 11] + 0.25*np.sqrt(15)*X[5, 11])
