	C[4,11] = l*(0.75*np.sqrt(10)*m**2*n**2*X[4, 10] - 7.5*m**2*n**2*X[5, 11] + 3.75*np.sqrt(2)*m**2*n**2*X[6, 12] + 0.25*np.sqrt(10)*m**2*X[4, 10] + 0.5*m**2*X[5, 11] - 0.75*np.sqrt(2)*m**2*X[6, 12] - 0.5*np.sqrt(10)*n**2*X[4, 10] + 1.25*n**2*X[5, 11] - 0.25*X[5, 11])
